const body = $json.body || $json;

function pick(...vals){
  for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; }
  return null;
}

// Một số nguồn Wazuh bọc dữ liệu gốc trong "all_fields"
const af = body.all_fields || body;

const rule  = af.rule  || {};
const agent = af.agent || {};
const data  = af.data  || {};
const syscheck = af.syscheck || data.syscheck || {};
const vt = data.virustotal || af.virustotal || {};
const win = data.win?.eventdata || {};
const sysmon = data.sysmon?.eventdata || {};

// ---- event_type ----
let event_type = body.event_type
  ?? (rule.id !== undefined || rule.level !== undefined ? 'wazuh_alert' : null)
  ?? 'unknown';

// ---- severity (text + numeric cho TheHive 1-4) ----
const ruleLevel = rule.level;
let severity = body.severity ?? body.risk_level
  ?? (ruleLevel >= 12 ? 'critical' : ruleLevel >= 10 ? 'high' : ruleLevel >= 7 ? 'medium' : ruleLevel !== undefined ? 'low' : 'medium');

let severity_num = ruleLevel !== undefined
  ? (ruleLevel >= 14 ? 4 : ruleLevel >= 10 ? 3 : ruleLevel >= 6 ? 2 : 1)
  : (severity === 'critical' ? 4 : severity === 'high' ? 3 : severity === 'low' ? 1 : 2);

// ---- src_ip: thử mọi nguồn khả dĩ (dashboard, wazuh rút gọn, wazuh raw EDR) ----
const src_ip = pick(
  body.src_ip, body.target,
  data.srcip, win.ipAddress, win.sourceIp, sysmon.sourceIp,
  agent.ip, 'N/A'
);

// ---- process / endpoint info (chỉ có ở Wazuh raw EDR) ----
const process_id = pick(win.processId, sysmon.processId, data.process?.pid, body.process_id, null);
const command_line = pick(win.commandLine, sysmon.commandLine, data.object?.process?.cmdline, null);
const file_hash = pick(syscheck.sha256_after, syscheck.sha256, vt.source?.sha256, vt.sha256, null);

// ---- MITRE ATT&CK ----
const mitre = rule.mitre || {};
const mitre_tactic = Array.isArray(mitre.tactic) ? mitre.tactic.join(', ') : (mitre.tactic || 'N/A');
const mitre_id = Array.isArray(mitre.id) ? mitre.id.join(', ') : (mitre.id || 'N/A');

const description = pick(body.attack_type, body.detection_type, body.verdict, rule.description, body.title, 'N/A');
const timestamp = body.timestamp ?? $now.toISO();
const reported_by = body.reported_by ?? 'system';
const wazuh_host = body.infrastructure?.wazuh_host ?? 'wazuh-server';
const agent_id = pick(agent.id, body.agent_id, '001');
const agent_name = agent.name ?? 'N/A';
const rule_groups = Array.isArray(rule.groups) ? rule.groups : [];
const confidence = body.confidence ?? 'N/A';

// ---- Markdown: PARSED EVENT FIELDS (flatten đệ quy, lọc field rác) ----
function flattenToMd(obj) {
  const blacklist = ['providerName','providerGuid','version','task','opcode','keywords',
    'eventRecordID','threadID','channel','severityValue','message','level','eventID','systemTime','computer'];
  let result = ''; let count = 0; const MAX = 40;
  function sanitize(v){ return String(v).replace(/`/g, "'").replace(/\n/g, ' ').replace(/\r/g, ' '); }
  function walk(o){
    for (const k in o){
      if (count >= MAX) return;
      if (blacklist.includes(k)) continue;
      const v = o[k];
      if (typeof v === 'object' && v !== null && !Array.isArray(v)) { walk(v); }
      else if (v !== '' && v !== null && v !== undefined) {
        result += '* **' + k + ':** `' + sanitize(v) + '`\n';
        count++;
      }
    }
  }
  walk(obj || {});
  return result || '*(Không có dữ liệu chi tiết)*';
}

const eventDataForFlatten = (data && Object.keys(data).length) ? data
  : (syscheck && Object.keys(syscheck).length) ? syscheck
  : (af.parameters || {});
const parsed_fields_md = flattenToMd(eventDataForFlatten);
const raw_json_md = JSON.stringify((af && Object.keys(af).length) ? af : body, null, 2);

return [{ json: {
  event_type, severity, severity_num, src_ip, confidence, description, timestamp,
  reported_by, wazuh_host, agent_id, agent_name, process_id, command_line, file_hash,
  rule_id: rule.id ?? 'N/A', rule_level: ruleLevel ?? 'N/A', rule_groups, mitre_tactic, mitre_id,
  parsed_fields_md, raw_json_md, _raw_body: JSON.stringify(body)
} }];

