function pick(...vals){ for (const v of vals){ if (v!==undefined && v!==null && v!=='') return v; } return null; }

const description = pick(src.description, norm.description, 'N/A');
const searchText = (description + ' ' + (norm.event_type || '')).toLowerCase();

let galaxyTag = null;
